const concepts=[
 {id:'inbox',name:'Recovery Inbox',file:'01-recovery-inbox.png',format:'DESKTOP + MOBILE / CONCEPT 01',number:'01 / START HERE',title:'A home for every unfinished purchase.',description:'Prioritize customers who need help, see payment and access side by side, and open the next investigation from one focused inbox.',alt:'Recovery Inbox concept: a desktop case list, selected purchase details, four specialist agents, and a matching mobile inbox.'},
 {id:'evidence',name:'Evidence Canvas',file:'02-evidence-canvas.png',format:'DESKTOP INVESTIGATION / CONCEPT 02',number:'02 / FOLLOW THE EVIDENCE',title:'See where payment and access diverge.',description:'Trace payment, enrollment, and access across connected evidence cards. Review each specialist’s finding and rehearse a specific correction before approving it.',alt:'Evidence Canvas concept: a customer panel, connected payment, enrollment and access records, four specialist findings, and a proposed correction.'},
 {id:'guided',name:'Guided Recovery',file:'03-guided-recovery.png',format:'THREE MOBILE SCREENS / CONCEPT 03',number:'03 / KEEP THE FINAL SAY',title:'One clear next step, wherever you are.',description:'A focused mobile journey: understand the issue, review and approve the correction, then inspect verification and prepare the customer response.',alt:'Guided Recovery concept: three mobile screens showing investigation, a specific access approval, and verification with a draft customer response.'}
];
const $=id=>document.getElementById(id);let selected=concepts[0],noticeTimer;const viewer=$('viewer');
function choose(){selected=concepts.find(c=>c.id===location.hash.slice(1))||concepts[0];const url='assets/ux/'+selected.file;document.querySelectorAll('[data-concept]').forEach(a=>{if(a.dataset.concept===selected.id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});$('screen').src=url;$('screen').alt=selected.alt;$('screen-link').href=url;$('screen-link').setAttribute('aria-label','Open '+selected.name+' mockup at full size');$('download').href=url;$('screen-format').textContent=selected.format;$('screen-number').textContent=selected.number;$('screen-title').textContent=selected.title;$('screen-description').textContent=selected.description;$('next').textContent='Next: '+concepts[(concepts.indexOf(selected)+1)%concepts.length].name+' →';$('viewer-title').textContent=selected.name;$('viewer-image').src=url;$('viewer-image').alt=selected.alt;setZoom(false);document.title=selected.name+' — PayTrace UX Gallery';if(location.hash==='#'+selected.id)document.querySelector('.gallery').scrollIntoView({block:'start'});}
function setZoom(actual){document.querySelector('.viewer-scroll').classList.toggle('actual',actual);$('zoom').setAttribute('aria-pressed',String(actual));$('zoom').textContent=actual?'Fit to screen':'Actual size';}
function notify(message){$('notice').textContent=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').textContent='',4000);}
async function share(screen){const url=new URL(location.href);url.hash=screen?selected.id:'';try{await navigator.clipboard.writeText(url.href);notify('Public '+(screen?'screen':'gallery')+' link copied.');}catch{notify('Copy the page address from your browser to share this gallery.');}}
$('share-gallery').onclick=()=>share(false);$('share-screen').onclick=()=>share(true);$('next').onclick=()=>{location.hash=concepts[(concepts.indexOf(selected)+1)%concepts.length].id;};$('expand').onclick=()=>{setZoom(false);viewer.showModal();};$('close').onclick=()=>viewer.close();$('zoom').onclick=()=>setZoom($('zoom').getAttribute('aria-pressed')!=='true');viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close();});window.addEventListener('hashchange',choose);choose();
